const BOM: &str = "\u{feff}";
const LINE_END: &str = "\r\n";
const LIST_SEPARATOR: &str = "\n";
/// Joins the values of a list on one line, when cells are not multi-line.
const INLINE_LIST_SEPARATOR: &str = " / ";
const LANGUAGES: [CardLanguage; 2] = [CardLanguage::Japanese, CardLanguage::English];

/// A column of the CSV. The export writes the chosen columns in the order of [`Column::ALL`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum Column {
    Deck,
    Quantity,
    CardNumber,
    Name,
    CardType,
    Color,
    Life,
    Hp,
    Rarity,
    SetCode,
    SetName,
    FullSetName,
    ProductCategory,
    ReleaseDate,
    PromoSource,
    Illustrator,
    Language,
    CardId,
    Variant,
    OfficialUrl,
    YuyuteiUrl,
    TcgplayerUrl,
    ImageUrl,
    ProxyUrl,
    PriceJpy,
    PriceUsd,
    Notes,
}

impl Column {
    /// Every column, in export order.
    pub const ALL: [Column; 27] = [
        Column::Deck,
        Column::Quantity,
        Column::CardNumber,
        Column::Name,
        Column::CardType,
        Column::Color,
        Column::Life,
        Column::Hp,
        Column::Rarity,
        Column::SetCode,
        Column::SetName,
        Column::FullSetName,
        Column::ProductCategory,
        Column::ReleaseDate,
        Column::PromoSource,
        Column::Illustrator,
        Column::Language,
        Column::CardId,
        Column::Variant,
        Column::OfficialUrl,
        Column::YuyuteiUrl,
        Column::TcgplayerUrl,
        Column::ImageUrl,
        Column::ProxyUrl,
        Column::PriceJpy,
        Column::PriceUsd,
        Column::Notes,
    ];

    pub fn header(self) -> &'static str {
        match self {
            Column::Deck => "Deck",
            Column::Quantity => "Quantity",
            Column::CardNumber => "Card Number",
            Column::Name => "Name",
            Column::CardType => "Card Type",
            Column::Color => "Color",
            Column::Life => "Life",
            Column::Hp => "HP",
            Column::Rarity => "Rarity",
            Column::SetName => "Set Name",
            Column::FullSetName => "Full Set Name",
            Column::SetCode => "Set Code",
            Column::ProductCategory => "Product Category",
            Column::ReleaseDate => "Release Date",
            Column::PromoSource => "Source",
            Column::Illustrator => "Illustrator",
            Column::Language => "Language",
            Column::CardId => "Card ID",
            Column::Variant => "Variant",
            Column::TcgplayerUrl => "TCGplayer URL",
            Column::YuyuteiUrl => "Yuyu-tei URL",
            Column::OfficialUrl => "Official URL",
            Column::ImageUrl => "Image URL",
            Column::ProxyUrl => "Proxy URL",
            Column::PriceJpy => "Price (JPY)",
            Column::PriceUsd => "Price (USD)",
            Column::Notes => "Notes",
        }
    }

    /// What the column holds, for a tooltip.
    pub fn description(self) -> &'static str {
        match self {
            Column::Deck => "Oshi, Main Deck or Cheer Deck",
            Column::Quantity => "Number of copies",
            Column::CardNumber => "e.g. hBP01-021",
            Column::Name => "In the name language",
            Column::CardType => "e.g. Debut Holo Member, Support - Event",
            Column::Color => "e.g. White, Green/Red",
            Column::Life => "Oshi life",
            Column::Hp => "Holo member HP",
            Column::Rarity => "e.g. C, OSR, P",
            Column::FullSetName => {
                "Official names of the products the printing is in, in the name language"
            }
            Column::SetName => {
                "Simplified product names in the name language, or their usual translation"
            }
            Column::SetCode => "Product codes, e.g. hSD01",
            Column::ProductCategory => "Category of the products on the official site",
            Column::ReleaseDate => "Earliest release date of the products",
            Column::PromoSource => {
                "How the printing was distributed in the release: promos, prizes, PR packs, and arts exclusive to a collection or set"
            }
            Column::Illustrator => "As credited",
            Column::Language => "JP or EN, the release of the printing in the row",
            Column::CardId => "Official card ids in the release",
            Column::Variant => "Card image path; identifies printings without a card id",
            Column::TcgplayerUrl => "TCGplayer product pages",
            Column::YuyuteiUrl => "Yuyu-tei product pages",
            Column::OfficialUrl => "Official card pages",
            Column::ImageUrl => "Card image",
            Column::ProxyUrl => {
                "Proxy image in the release language, for a printing not released in it"
            }
            Column::PriceJpy => "Lowest Yuyu-tei price, from the last price check",
            Column::PriceUsd => "Lowest TCGplayer price, from the last price check",
            Column::Notes => "e.g. Not released in English (proxy)",
        }
    }

    /// Columns the import needs to find the exact printings again (and to rebuild a deck).
    pub fn is_required(self, deck: bool) -> bool {
        matches!(
            self,
            Column::Quantity | Column::Language | Column::CardId | Column::Variant
        ) || (deck && self == Column::Deck)
    }

    /// Exported unless unchecked: the store of the release (Yuyu-tei for Japanese cards,
    /// TCGplayer for English ones), and the usual columns.
    pub fn is_default(self, release: CardLanguage) -> bool {
        match self {
            Column::YuyuteiUrl => return release == CardLanguage::Japanese,
            Column::TcgplayerUrl => return release == CardLanguage::English,
            _ => {}
        }
        !matches!(
            self,
            Column::CardType
                | Column::Color
                | Column::Life
                | Column::Hp
                | Column::FullSetName
                | Column::ProductCategory
                | Column::ProxyUrl
                | Column::PriceJpy
                | Column::PriceUsd
        )
    }

    /// The columns to export, in export order: the required ones, and the chosen ones
    /// (`choices` holds the columns changed from their default).
    pub fn selection(
        choices: &BTreeMap<Column, bool>,
        deck: bool,
        release: CardLanguage,
    ) -> Vec<Column> {
        Column::ALL
            .into_iter()
            .filter(|c| deck || *c != Column::Deck)
            .filter(|c| {
                c.is_required(deck)
                    || choices
                        .get(c)
                        .copied()
                        .unwrap_or_else(|| c.is_default(release))
            })
            .collect()
    }

    #[cfg(test)]
    pub fn defaults(deck: bool, release: CardLanguage) -> Vec<Column> {
        Column::selection(&BTreeMap::new(), deck, release)
    }

    /// Recognizes a header, ignoring case, spaces and punctuation.
    fn from_header(header: &str) -> Option<Column> {
        let key: String = header
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(char::to_lowercase)
            .collect();
        Some(match key.as_str() {
            "deck" | "zone" | "board" | "pile" => Column::Deck,
            "quantity" | "qty" | "amount" | "count" | "copies" | "owned" | "have" | "total"
            | "numberofcards" | "枚数" | "数量" => Column::Quantity,
            "cardnumber"
            | "cardno"
            | "cardnum"
            | "number"
            | "no"
            | "num"
            | "cardcode"
            | "code"
            | "card"
            | "カード番号"
            | "カードナンバー" => Column::CardNumber,
            "name" | "cardname" | "title" | "カード名" | "名前" => Column::Name,
            "rarity" | "rare" | "rar" | "レアリティ" => Column::Rarity,
            "set" | "setname" | "setshortname" | "product" | "products" | "pack" | "edition"
            | "cardset" | "fullsetname" | "収録商品" => Column::SetName,
            "setcode" | "expansion" | "expansioncode" | "productcode" | "setid" => Column::SetCode,
            "releasedate" | "release" | "date" | "発売日" => Column::ReleaseDate,
            "illustrator"
            | "illustrators"
            | "artist"
            | "illust"
            | "illustration"
            | "イラストレーター" => Column::Illustrator,
            "language" | "lang" | "region" | "言語" => Column::Language,
            "cardid" | "cardids" | "manageid" | "officialid" | "id" => Column::CardId,
            "variant" | "image" | "imagepath" | "img" | "imgpath" | "art" => Column::Variant,
            "tcgplayerid" | "tcgplayerids" | "tcgplayerproductid" | "tcgplayer" | "productid"
            | "tcgplayerurl" => Column::TcgplayerUrl,
            "yuyuteiurl" | "yuyuteiurls" | "yuyutei" | "yuyuteipath" | "yuyuteiid" => {
                Column::YuyuteiUrl
            }
            "officialurl" | "url" | "officialsite" | "link" => Column::OfficialUrl,
            "imageurl" | "imgurl" | "imagelink" => Column::ImageUrl,
            "notes" | "note" | "comment" | "comments" | "remarks" => Column::Notes,
            _ => return None,
        })
    }

    /// Columns that can identify a card (`Set` and `Set Code` sometimes hold card numbers).
    fn identifies_card(self) -> bool {
        matches!(
            self,
            Column::CardNumber
                | Column::SetName
                | Column::SetCode
                | Column::CardId
                | Column::Variant
                | Column::TcgplayerUrl
                | Column::YuyuteiUrl
                | Column::OfficialUrl
                | Column::ImageUrl
        )
    }
}

fn lang_code(language: CardLanguage) -> &'static str {
    match language {
        CardLanguage::Japanese => "JP",
        CardLanguage::English => "EN",
    }
}

fn lang_name(language: CardLanguage) -> &'static str {
    match language {
        CardLanguage::Japanese => "Japanese",
        CardLanguage::English => "English",
    }
}

fn parse_language(value: &str) -> Option<CardLanguage> {
    match value.trim().to_lowercase().as_str() {
        "jp" | "ja" | "jpn" | "jap" | "japanese" | "japan" | "日本語" | "日本" => {
            Some(CardLanguage::Japanese)
        }
        "en" | "eng" | "english" | "英語" => Some(CardLanguage::English),
        _ => None,
    }
}

fn join(values: impl IntoIterator<Item = impl Display>) -> String {
    values.into_iter().join(LIST_SEPARATOR)
}

// ---------------------------------------------------------------------------------------------
// Printing attributes
// ---------------------------------------------------------------------------------------------

/// An image path without its extension.
fn image_stem(path: &str) -> &str {
    match path.rsplit_once('.') {
        Some((stem, ext)) if !ext.contains('/') => stem,
        _ => path,
    }
}

/// The image path of a printing without extension, e.g. `hPR/hBP09-094_P_02`, in a language or
/// else the other one. Image paths are unique, so this identifies printings without a card id.
fn variant(illust: &CardIllustration, language: CardLanguage) -> Option<String> {
    [language, other_lang(language)]
        .into_iter()
        .find_map(|lang| illust.img_path.value(lang.into()).as_deref())
        .map(|path| image_stem(path).to_string())
}

/// Image folders of the assets repo that are not named after a set: images shared by several
/// products, and images of printings that are not released yet.
const NON_SET_IMAGE_FOLDERS: [&str; 2] = ["COMMON", "unreleased"];

/// The set code of a printing without products, from where the assets repo stores its image:
/// each image is in a folder named after its set (`hBP09/hBP09-094_U.webp`, proxies in
/// `proxies/hPR/…`). When that folder is not a set (see [`NON_SET_IMAGE_FOLDERS`]), the other
/// language's folder is used if it is one.
fn image_set_code(illust: &CardIllustration, language: CardLanguage) -> Option<String> {
    let folder = |language: CardLanguage| {
        let path = illust.img_path.value(language.into()).as_deref()?;
        let (dir, _) = path.rsplit_once('/')?;
        Some(dir.rsplit('/').next().unwrap_or(dir).to_string())
    };
    let folders = [folder(language), folder(other_lang(language))];
    let is_set = |folder: &&String| !NON_SET_IMAGE_FOLDERS.contains(&folder.as_str());
    let mut folders = folders.iter().flatten();
    folders
        .clone()
        .find(is_set)
        .or_else(|| folders.next())
        .cloned()
}

/// The catalog entries of the products the printing is in (see [`products_language`]); codes
/// missing from the catalog are left out.
fn catalog_products<'a>(
    illust: &'a CardIllustration,
    language: CardLanguage,
    catalog: &'a ProductsDatabase,
) -> impl Iterator<Item = &'a Product> {
    illust
        .products_in(products_language(illust, language).into(), catalog)
        .into_iter()
        .filter_map(|(_, product)| product)
}

/// `Full Set Name`: official names, in the name language (else the other one), of the products of the
/// printing in the release language.
fn set_names(
    illust: &CardIllustration,
    language: CardLanguage,
    names: CardLanguage,
    catalog: &ProductsDatabase,
) -> String {
    join(catalog_products(illust, language, catalog).filter_map(|p| official_name(p, names)))
}

/// `Set Name`: simplified official names in the name language, else the unofficial
/// translation (for a product released only in the other language), else the other language's.
fn set_short_names(
    illust: &CardIllustration,
    language: CardLanguage,
    names: CardLanguage,
    catalog: &ProductsDatabase,
) -> String {
    let names = catalog_products(illust, language, catalog).filter_map(|p| {
        [names, other_lang(names)]
            .into_iter()
            .find_map(|l| p.display_name(l.into(), true))
            .map(|(name, _)| name)
    });
    join(names)
}

fn product_categories(
    illust: &CardIllustration,
    language: CardLanguage,
    catalog: &ProductsDatabase,
) -> String {
    let categories = catalog_products(illust, language, catalog)
        .filter_map(|p| p.category.as_deref())
        .unique();
    join(categories)
}

/// `Set Code`: the products' expansion codes, else the image set code.
fn set_codes(illust: &CardIllustration, language: CardLanguage) -> String {
    let codes = product_codes(illust, products_language(illust, language));
    if codes.is_empty() {
        image_set_code(illust, language).unwrap_or_default()
    } else {
        join(codes)
    }
}

/// `Release Date`: the earliest release in the release language of the products the printing is
/// released in, in that language.
fn release_date(
    illust: &CardIllustration,
    language: CardLanguage,
    catalog: &ProductsDatabase,
) -> String {
    illust
        .products_in(language.into(), catalog)
        .into_iter()
        .filter_map(|(_, product)| product?.release_date.value(language.into()).as_deref())
        .min()
        .unwrap_or_default()
        .to_string()
}

fn manage_ids(illust: &CardIllustration, language: CardLanguage) -> impl Iterator<Item = u32> {
    illust
        .manage_id
        .value(language.into())
        .iter()
        .flatten()
        .copied()
}

/// A price as a plain number, for spreadsheets.
fn price_number(price: Price) -> String {
    match price {
        Price::Zero => "0".into(),
        Price::Yen(yen) => yen.to_string(),
        Price::Dollar(cents) => format!("{}.{:02}", cents / 100, cents % 100),
    }
}

/// The assets repo stores the proxies it makes under `proxies/`.
fn is_proxy(path: &str) -> bool {
    path.contains("proxies")
}

/// The release a row describes: the chosen one, or the other one for a printing released only
/// in it (its card ids, URLs and images are all from that release). A printing not released
/// yet goes by its products, else its image (not a proxy).
fn row_language(illust: &CardIllustration, release: CardLanguage) -> CardLanguage {
    let released = |language: CardLanguage| illust.manage_id.value(language.into()).is_some();
    let announced = |language: CardLanguage| {
        !product_codes(illust, language).is_empty()
            || illust
                .img_path
                .value(language.into())
                .as_deref()
                .is_some_and(|path| !is_proxy(path))
    };
    let other = other_lang(release);
    if released(release) || (!released(other) && (announced(release) || !announced(other))) {
        release
    } else {
        other
    }
}

/// `Proxy URL`: the proxy image in the release, of a printing not released in it.
fn proxy_url(card: &CommonCard, release: CardLanguage, db: &CardsDatabase) -> String {
    let Some(illust) = card.card_illustration(db) else {
        return String::new();
    };
    let has_proxy = illust
        .img_path
        .value(release.into())
        .as_deref()
        .is_some_and(is_proxy);
    if has_proxy && row_language(illust, release) != release {
        card.image_path(db, release, ImageOptions::card_details())
            .unwrap_or_default()
    } else {
        String::new()
    }
}

/// Why a row is not in the chosen release, or what is unknown about it.
/// The `Notes` of a card, also shown on the card in the app.
pub fn notes(card: &CommonCard, language: CardLanguage, db: &CardsDatabase) -> String {
    let Some(illust) = card.card_illustration(db) else {
        return "Unknown card".into();
    };
    if !illust.manage_id.has_value() {
        return "Unreleased printing".into();
    }
    if illust.manage_id.value(language.into()).is_none() {
        // the assets repo only has an image in a language the printing is not released in
        // when it made a proxy of it
        let proxy = if illust.img_path.value(language.into()).is_some() {
            " (proxy)"
        } else {
            ""
        };
        return format!("Not released in {}{proxy}", lang_name(language));
    }
    String::new()
}

// ---------------------------------------------------------------------------------------------
// Export
// ---------------------------------------------------------------------------------------------

/// What the export reads from: the card database, the product catalog (may be empty) and the
/// prices from the last price check (may be empty).
pub struct ExportData<'a> {
    pub db: &'a CardsDatabase,
    pub catalog: &'a ProductsDatabase,
    pub prices: &'a PriceCache,
}

/// How the export is written.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ExportOptions {
    /// The release of the cards: which printing, card ids, URLs, images and release dates.
    pub release: CardLanguage,
    /// The language of the names: card, set, card type and color names.
    pub names: CardLanguage,
    /// Lists one value per line (a quoted cell with line breaks), else joined with " / ".
    pub multi_line: bool,
}

impl ExportOptions {
    /// Names in the language of the release, one value per line.
    #[cfg(test)]
    pub fn new(language: CardLanguage) -> Self {
        ExportOptions {
            release: language,
            names: language,
            multi_line: true,
        }
    }
}

fn cell(
    column: Column,
    section: Option<&str>,
    card: &CommonCard,
    options: &ExportOptions,
    data: &ExportData,
) -> String {
    let ExportOptions { release, names, .. } = *options;
    let ExportData {
        db,
        catalog,
        prices,
    } = *data;
    let (Some(info), Some(illust)) = (card.card_info(db), card.card_illustration(db)) else {
        // unknown card: only what the deck knows
        return match column {
            Column::Deck => section.unwrap_or_default().into(),
            Column::Quantity => card.amount.to_string(),
            Column::CardNumber => card.card_number.clone(),
            Column::Language => lang_code(release).into(),
            Column::Notes => notes(card, release, db),
            _ => String::new(),
        };
    };
    let language = row_language(illust, release);
    let price = |service| {
        card.price(db, prices, service, false)
            .map(|(_, price)| price_number(price))
            .unwrap_or_default()
    };
    let positive = |value: u32| {
        if value > 0 {
            value.to_string()
        } else {
            String::new()
        }
    };
    match column {
        Column::Deck => section.unwrap_or_default().into(),
        Column::Quantity => card.amount.to_string(),
        Column::CardNumber => card.card_number.clone(),
        Column::Name => info
            .name
            .value(names.into())
            .as_ref()
            .or(info.name.value(other_lang(names).into()).as_ref())
            .cloned()
            .unwrap_or_default(),
        Column::CardType => card_type_label(info, names),
        Column::Color => info
            .colors
            .iter()
            .filter_map(|c| color_label(*c, names))
            .join("/"),
        Column::Life => positive(info.life),
        Column::Hp => positive(info.hp),
        Column::Rarity => illust.rarity.to_string(),
        Column::SetName => set_short_names(illust, language, names, catalog),
        Column::FullSetName => set_names(illust, language, names, catalog),
        Column::SetCode => set_codes(illust, language),
        Column::ProductCategory => product_categories(illust, language, catalog),
        Column::ReleaseDate => release_date(illust, language, catalog),
        Column::PromoSource => join(illust.promo_sources.value(language.into()).iter().flatten()),
        Column::Illustrator => illust.illustrator.clone().unwrap_or_default(),
        Column::Language => lang_code(language).into(),
        Column::CardId => join(manage_ids(illust, language)),
        Column::Variant => variant(illust, language).unwrap_or_default(),
        Column::TcgplayerUrl => join(illust.tcgplayer_urls()),
        Column::YuyuteiUrl => join(illust.yuyutei_urls()),
        Column::OfficialUrl => {
            let urls = illust.official_site_urls(language.into());
            if urls.is_empty() {
                join(illust.official_site_urls(other_lang(language).into()))
            } else {
                join(urls)
            }
        }
        Column::ImageUrl => card
            .image_path(db, language, ImageOptions::card_details())
            .unwrap_or_default(),
        Column::ProxyUrl => proxy_url(card, release, db),
        Column::PriceJpy => price(PriceCheckService::Yuyutei),
        Column::PriceUsd => price(PriceCheckService::TcgPlayer),
        Column::Notes => notes(card, release, db),
    }
}

fn write_record<'a>(out: &mut String, fields: impl IntoIterator<Item = &'a str>) {
    for (i, field) in fields.into_iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        let needs_quotes = field.contains([',', '"', '\r', '\n'])
            || field.starts_with(char::is_whitespace)
            || field.ends_with(char::is_whitespace);
        if needs_quotes {
            out.push('"');
            out.push_str(&field.replace('"', "\"\""));
            out.push('"');
        } else {
            out.push_str(field);
        }
    }
    out.push_str(LINE_END);
}

/// Exports a deck (with a `Deck` column) or a pile as CSV text, without BOM. Writes the
/// required columns and the given ones that are not empty on every row, in the order of
/// [`Column::ALL`].
pub fn export_csv(
    deck: &DeckOrPile,
    data: &ExportData,
    columns: &[Column],
    options: &ExportOptions,
) -> String {
    let rows: Vec<(Option<&str>, &CommonCard)> = match deck {
        DeckOrPile::Deck(deck) => deck
            .oshi
            .iter()
            .map(|c| (Some("Oshi"), c))
            .chain(deck.main_deck.iter().map(|c| (Some("Main Deck"), c)))
            .chain(deck.cheer_deck.iter().map(|c| (Some("Cheer Deck"), c)))
            .collect(),
        DeckOrPile::Pile(pile) => pile.cards.iter().map(|c| (None, c)).collect(),
    };
    let is_deck = matches!(deck, DeckOrPile::Deck(_));
    let columns = Column::ALL
        .into_iter()
        .filter(|c| is_deck || *c != Column::Deck)
        .filter(|c| c.is_required(is_deck) || columns.contains(c))
        .collect_vec();

    let records = rows
        .into_iter()
        .filter(|(_, c)| c.amount > 0)
        .map(|(section, card)| {
            columns
                .iter()
                .map(|c| cell(*c, section, card, options, data))
                .map(|cell| {
                    if options.multi_line {
                        cell
                    } else {
                        cell.replace(LIST_SEPARATOR, INLINE_LIST_SEPARATOR)
                    }
                })
                .collect_vec()
        })
        .collect_vec();
    // an optional column that is empty on every row is left out
    let kept = (0..columns.len())
        .filter(|&i| columns[i].is_required(is_deck) || records.iter().any(|r| !r[i].is_empty()))
        .collect_vec();

    let mut out = String::new();
    write_record(&mut out, kept.iter().map(|&i| columns[i].header()));
    for record in &records {
        write_record(&mut out, kept.iter().map(|&i| record[i].as_str()));
    }
    out
}

/// The CSV file: UTF-8 with BOM, so spreadsheet apps show Japanese text correctly.
pub fn export_csv_file(
    deck: &DeckOrPile,
    data: &ExportData,
    columns: &[Column],
    options: &ExportOptions,
) -> Vec<u8> {
    format!("{BOM}{}", export_csv(deck, data, columns, options)).into_bytes()
}

// ---------------------------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------------------------

/// Picks the delimiter that appears most in the first line (outside quotes).
fn detect_delimiter(text: &str) -> char {
    let mut counts = [(',', 0), (';', 0), ('\t', 0)];
    let mut in_quotes = false;
    for c in text.chars() {
        match c {
            '"' => in_quotes = !in_quotes,
            '\n' | '\r' if !in_quotes => break,
            _ if !in_quotes => {
                if let Some(count) = counts.iter_mut().find(|(d, _)| *d == c) {
                    count.1 += 1;
                }
            }
            _ => {}
        }
    }
    counts
        .iter()
        .max_by_key(|(_, count)| *count)
        .filter(|(_, count)| *count > 0)
        .map_or(',', |(d, _)| *d)
}

/// Parses RFC 4180 records. Returns the 1-based record number with each non-empty record.
fn parse_records(text: &str, delimiter: char) -> Vec<(usize, Vec<String>)> {
    let mut records = vec![];
    let mut record = vec![];
    let mut field = String::new();
    let mut in_quotes = false;
    let mut record_number = 1;
    let mut chars = text.chars().peekable();

    let mut end_record = |record: &mut Vec<String>, field: &mut String, number: &mut usize| {
        record.push(std::mem::take(field));
        if record.iter().any(|f| !f.trim().is_empty()) {
            records.push((*number, std::mem::take(record)));
        } else {
            record.clear();
        }
        *number += 1;
    };

    while let Some(c) = chars.next() {
        if in_quotes {
            match c {
                '"' if chars.peek() == Some(&'"') => {
                    chars.next();
                    field.push('"');
                }
                '"' => in_quotes = false,
                _ => field.push(c),
            }
        } else {
            match c {
                '"' if field.trim().is_empty() => {
                    field.clear();
                    in_quotes = true;
                }
                '\r' => {
                    if chars.peek() == Some(&'\n') {
                        chars.next();
                    }
                    end_record(&mut record, &mut field, &mut record_number);
                }
                '\n' => end_record(&mut record, &mut field, &mut record_number),
                _ if c == delimiter => record.push(std::mem::take(&mut field)),
                _ => field.push(c),
            }
        }
    }
    if !field.is_empty() || !record.is_empty() {
        end_record(&mut record, &mut field, &mut record_number);
    }
    records
}

fn parse_quantity(value: &str) -> Option<u32> {
    let value = value
        .trim()
        .trim_matches(|c: char| c == 'x' || c == 'X' || c == '×');
    value.trim().parse().ok()
}

fn parse_section(value: &str) -> Option<CardType> {
    let value = value.trim().to_lowercase();
    match value.as_str() {
        "oshi" | "oshi holomem" | "oshi holo member" | "推し" | "推しホロメン" => {
            Some(CardType::Oshi)
        }
        "main" | "main deck" | "deck" | "メイン" | "メインデッキ" | "デッキ" => {
            Some(CardType::Main)
        }
        "cheer" | "cheer deck" | "yell" | "エール" | "エールデッキ" => {
            Some(CardType::Cheer)
        }
        _ => None,
    }
}

/// The values of a cell that can hold several, e.g. `645588 / 645590` or two URLs.
fn cell_values(value: &str) -> Vec<String> {
    value
        .split(|c: char| c.is_whitespace() || matches!(c, '|' | ';' | ','))
        .filter(|v| v.chars().any(char::is_alphanumeric))
        .map(String::from)
        .collect()
}

/// The numbers in a cell, e.g. `2811` or `2811 / 2812`.
fn cell_numbers(value: &str) -> Vec<u32> {
    value
        .split(|c: char| !c.is_ascii_digit())
        .filter_map(|v| v.parse().ok())
        .collect()
}

/// A URL for comparison: without case, scheme, `www.`, fragment or trailing slash.
fn url_key(url: &str) -> String {
    let url = url.trim().split('#').next().unwrap_or_default();
    let url = url.split_once("://").map_or(url, |(_, rest)| rest);
    let url = url.strip_prefix("www.").unwrap_or(url);
    url.trim_end_matches('/').to_lowercase()
}

/// The keys to look a URL from the file up with, longest first: the URL, then the URL cut at
/// each `/`, `?` or `&`, so a link with extra path or query (TCGplayer links end with a slug)
/// still finds the URL the model makes.
fn url_lookup_keys(value: &str) -> Vec<String> {
    let key = url_key(value);
    let cuts = key
        .char_indices()
        .rev()
        .filter(|(_, c)| matches!(c, '/' | '?' | '&'))
        .map(|(i, _)| key[..i].trim_end_matches('/').to_string())
        .filter(|k| k.contains('/'))
        .collect_vec();
    [vec![key], cuts].concat()
}

/// The card number as written in the database, when `value` is one.
fn known_card_number(value: &str, db: &CardsDatabase) -> Option<String> {
    let value = value.trim();
    db.get(value)
        .or_else(|| {
            db.values()
                .find(|c| c.card_number.eq_ignore_ascii_case(value))
        })
        .map(|c| c.card_number.clone())
}

// ---------------------------------------------------------------------------------------------
// Import
// ---------------------------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IssueKind {
    /// The row was not imported.
    Skipped,
    /// The row was imported, but the printing might not be the intended one.
    Loose,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ImportIssue {
    /// Row in the file, the header being row 1.
    pub row: usize,
    pub kind: IssueKind,
    pub message: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CsvImport {
    pub deck: DeckOrPile,
    /// Data rows that were read.
    pub rows: usize,
    pub issues: Vec<ImportIssue>,
}

#[derive(Debug, Default)]
struct Row {
    card_number: Option<String>,
    rarity: Option<String>,
    set: Option<String>,
    set_code: Option<String>,
    illustrator: Option<String>,
    language: Option<CardLanguage>,
    card_ids: Vec<u32>,
    official_urls: Vec<String>,
    /// From `Variant` and `Image URL`.
    variants: Vec<String>,
    /// TCGplayer product ids or URLs.
    tcgplayer: Vec<String>,
    /// Yuyu-tei URLs or sell paths.
    yuyutei: Vec<String>,
}

impl Row {
    fn number_matches(&self, card: &CommonCard) -> bool {
        self.card_number
            .as_ref()
            .is_none_or(|n| n.eq_ignore_ascii_case(&card.card_number))
    }
}

enum Matched {
    Exact(CommonCard),
    Loose(CommonCard, String),
}

/// TCGplayer's rarity names (the `Rarity` field of its hololive catalog, checked against every
/// set listed on tcgcsv.com on 2026-11-15) with the rarity codes the database uses. These names
/// cannot be derived from the codes ("Double Rare" is RR, "Secret Rare" is SEC, "Special Yell" is
/// SY), so they are listed here only to read TCGplayer exports. Anything else, including a name
/// TCGplayer adds later, is read as a code by the model, and a rarity that matches no printing
/// only makes the row a loose match.
const TCGPLAYER_RARITIES: [(&str, &str); 14] = [
    ("Common", "C"),
    ("Uncommon", "U"),
    ("Rare", "R"),
    ("Double Rare", "RR"),
    ("Super Rare", "SR"),
    ("Ultra Rare", "UR"),
    ("Secret Rare", "SEC"),
    ("Holomem Rare", "HR"),
    ("Oshi Common", "OC"),
    ("Oshi Super Rare", "OSR"),
    ("Oshi Ultra Rare", "OUR"),
    ("Special", "S"),
    ("Special Yell", "SY"),
    ("Promo", "P"),
];

fn rarity_matches(illust: &CardIllustration, value: &str) -> bool {
    let value = value.trim();
    let code = TCGPLAYER_RARITIES
        .iter()
        .find(|(name, _)| name.eq_ignore_ascii_case(value))
        .map_or(value, |(_, code)| code);
    illust.rarity == CardRarity::from(code.to_string())
}

/// Set codes of a printing in any language: the products' expansion codes and the image set code.
fn all_set_codes(illust: &CardIllustration) -> Vec<String> {
    LANGUAGES
        .iter()
        .flat_map(|l| product_codes(illust, *l))
        .cloned()
        .chain(LANGUAGES.iter().filter_map(|l| image_set_code(illust, *l)))
        .map(|c| c.to_lowercase())
        .unique()
        .collect()
}

/// Catalog names (official, short and unofficial, in both languages) of the products of a
/// printing in any language.
fn all_set_names(illust: &CardIllustration, catalog: &ProductsDatabase) -> Vec<String> {
    LANGUAGES
        .iter()
        .flat_map(|l| illust.products_in((*l).into(), catalog))
        .filter_map(|(_, product)| product)
        .flat_map(|p| [&p.name, &p.short_name, &p.unofficial_name])
        .flat_map(|name| [&name.japanese, &name.english])
        .flatten()
        .map(|name| name.to_lowercase())
        .unique()
        .collect()
}

fn set_code_matches(illust: &CardIllustration, value: &str) -> bool {
    let codes = all_set_codes(illust);
    cell_values(value)
        .iter()
        .any(|v| codes.contains(&v.to_lowercase()))
}

/// A set name, a set code, or text containing either (e.g. "Booster Pack hBP09: Volume Vortex").
fn set_matches(illust: &CardIllustration, value: &str, catalog: &ProductsDatabase) -> bool {
    let value = value.trim().to_lowercase();
    let codes = all_set_codes(illust);
    let names = all_set_names(illust, catalog);
    let words_contain_code = value
        .split(|c: char| !c.is_alphanumeric())
        .any(|word| codes.iter().any(|code| code == word));
    let names_match = value
        .split('\n')
        .flat_map(|line| line.split(" / "))
        .map(str::trim)
        .any(|part| names.iter().any(|name| name == part))
        || (value.chars().count() >= 4 && names.iter().any(|name| name.contains(&value)));
    codes.contains(&value) || words_contain_code || names_match
}

fn illustrator_matches(illust: &CardIllustration, value: &str) -> bool {
    let value = value.trim().to_lowercase();
    illust
        .illustrator
        .as_deref()
        .unwrap_or_default()
        .trim()
        .to_lowercase()
        == value
}

/// An image path or URL from the file, as a lowercase image path without extension.
fn normalize_variant(value: &str) -> String {
    let value = value.trim().replace('\\', "/");
    let value = value.split(['?', '#']).next().unwrap_or_default();
    image_stem(value.trim_start_matches('/')).to_lowercase()
}

/// Lookups from the identifiers a file can hold to printings, built once per import so that
/// large collections don't scan the database for every row. Every key comes from the database
/// or the model's URL helpers.
struct DbIndex<'a> {
    /// `(illustration index, printing)` in database order; the maps point into it.
    printings: Vec<(usize, &'a CardIllustration)>,
    manage_ids: HashMap<(CardLanguage, u32), Vec<usize>>,
    official_urls: HashMap<String, Vec<usize>>,
    /// Lowercase image paths without extension, in both languages.
    variants: HashMap<String, Vec<usize>>,
    /// Lowercase image file names without extension.
    file_names: HashMap<String, Vec<usize>>,
    tcgplayer_ids: HashMap<u32, Vec<usize>>,
    tcgplayer_urls: HashMap<String, Vec<usize>>,
    /// Yuyu-tei URLs and sell paths.
    yuyutei: HashMap<String, Vec<usize>>,
}

fn add_key<K: Hash + Eq>(map: &mut HashMap<K, Vec<usize>>, key: K, printing: usize) {
    let printings = map.entry(key).or_default();
    if printings.last() != Some(&printing) {
        printings.push(printing);
    }
}

impl<'a> DbIndex<'a> {
    fn new(db: &'a CardsDatabase) -> Self {
        let printings = db
            .values()
            .flat_map(|c| c.illustrations.iter().enumerate())
            .collect_vec();
        let mut index = DbIndex {
            printings: vec![],
            manage_ids: HashMap::new(),
            official_urls: HashMap::new(),
            variants: HashMap::new(),
            file_names: HashMap::new(),
            tcgplayer_ids: HashMap::new(),
            tcgplayer_urls: HashMap::new(),
            yuyutei: HashMap::new(),
        };
        for (p, (_, illust)) in printings.iter().enumerate() {
            for language in LANGUAGES {
                for id in manage_ids(illust, language) {
                    add_key(&mut index.manage_ids, (language, id), p);
                }
                for url in illust.official_site_urls(language.into()) {
                    add_key(&mut index.official_urls, url_key(&url), p);
                }
                if let Some(path) = illust.img_path.value(language.into()) {
                    let stem = image_stem(path).to_lowercase();
                    let file_name = stem.rsplit('/').next().unwrap_or(&stem).to_string();
                    add_key(&mut index.variants, stem, p);
                    add_key(&mut index.file_names, file_name, p);
                }
            }
            for id in illust.tcgplayer_product_ids.iter().flatten() {
                add_key(&mut index.tcgplayer_ids, *id, p);
            }
            for url in illust.tcgplayer_urls() {
                add_key(&mut index.tcgplayer_urls, url_key(&url), p);
            }
            for url in illust.yuyutei_urls() {
                add_key(&mut index.yuyutei, url_key(&url), p);
            }
            for path in illust.yuyutei_sell_paths.iter().flatten() {
                add_key(&mut index.yuyutei, path.trim_matches('/').to_lowercase(), p);
            }
        }
        index.printings = printings;
        index
    }

    /// The printings of the first key found in `map`.
    fn first_hit<K: Hash + Eq>(
        map: &HashMap<K, Vec<usize>>,
        keys: impl IntoIterator<Item = K>,
    ) -> Vec<usize> {
        keys.into_iter()
            .find_map(|key| map.get(&key))
            .cloned()
            .unwrap_or_default()
    }

    fn by_card_ids(&self, ids: &[u32], languages: &[CardLanguage]) -> Vec<usize> {
        languages
            .iter()
            .cartesian_product(ids)
            .flat_map(|(l, id)| self.manage_ids.get(&(*l, *id)).into_iter().flatten())
            .copied()
            .collect()
    }

    fn by_official_url(&self, url: &str) -> Vec<usize> {
        Self::first_hit(&self.official_urls, url_lookup_keys(url))
    }

    /// The same image path, a URL or longer path ending with one, or just a file name.
    fn by_variant(&self, value: &str) -> Vec<usize> {
        if !value.contains('/') {
            return Self::first_hit(&self.file_names, [value.to_string()]);
        }
        let suffixes = std::iter::once(value).chain(
            value
                .match_indices('/')
                .map(|(i, _)| &value[i + 1..])
                .filter(|s| s.contains('/')),
        );
        Self::first_hit(&self.variants, suffixes.map(String::from))
    }

    fn by_tcgplayer(&self, value: &str) -> Vec<usize> {
        match value.parse::<u32>() {
            Ok(id) => Self::first_hit(&self.tcgplayer_ids, [id]),
            Err(_) => Self::first_hit(&self.tcgplayer_urls, url_lookup_keys(value)),
        }
    }

    fn by_yuyutei(&self, value: &str) -> Vec<usize> {
        let path = value.trim().trim_matches('/').to_lowercase();
        Self::first_hit(
            &self.yuyutei,
            url_lookup_keys(value).into_iter().chain([path]),
        )
    }

    fn card(&self, printing: usize, amount: u32) -> CommonCard {
        let (idx, illust) = self.printings[printing];
        CommonCard::from_card_number_and_illustration_idx(illust.card_number.clone(), idx, amount)
    }
}

/// Matches by card number, narrowed down by rarity, set code, set and illustrator.
fn match_by_attributes(
    row: &Row,
    amount: u32,
    db: &CardsDatabase,
    catalog: &ProductsDatabase,
) -> Result<Matched, String> {
    let Some(card_number) = &row.card_number else {
        return Err("No card number, and no other column matches a card.".into());
    };
    // the card number is as written in the database when it is a known one
    let candidates = db
        .get(card_number)
        .into_iter()
        .flat_map(|c| c.illustrations.iter().enumerate())
        .collect_vec();
    if candidates.is_empty() {
        return Err(format!("Unknown card number \"{card_number}\"."));
    }

    let set_matches = |illust: &CardIllustration, value: &str| set_matches(illust, value, catalog);
    type Filter<'a> = &'a dyn Fn(&CardIllustration, &str) -> bool;
    let filters: Vec<(&str, &str, Filter)> = [
        ("rarity", row.rarity.as_deref(), &rarity_matches as Filter),
        ("set code", row.set_code.as_deref(), &set_code_matches),
        ("set", row.set.as_deref(), &set_matches),
        (
            "illustrator",
            row.illustrator.as_deref(),
            &illustrator_matches,
        ),
    ]
    .into_iter()
    .filter_map(|(name, value, filter)| Some((name, value?, filter)))
    .collect();

    let mut remaining = candidates;
    let mut ignored = vec![];
    let mut used = vec![];
    for (name, value, filter) in filters {
        let next = remaining
            .iter()
            .filter(|(_, i)| filter(i, value))
            .copied()
            .collect_vec();
        if next.is_empty() {
            ignored.push(format!("{name} \"{value}\""));
        } else {
            used.push(name);
            remaining = next;
        }
    }

    let (idx, illust) = remaining[0];
    let card =
        CommonCard::from_card_number_and_illustration_idx(illust.card_number.clone(), idx, amount);
    if remaining.len() == 1 && ignored.is_empty() {
        return Ok(Matched::Exact(card));
    }

    let mut reasons = vec![];
    if !ignored.is_empty() {
        reasons.push(format!(
            "no {} printing with {}",
            illust.card_number,
            ignored.join(", ")
        ));
    }
    if remaining.len() > 1 {
        let by = match used.split_last() {
            None => "the card number".to_string(),
            Some((last, rest)) => {
                let first = ["card number"].iter().chain(rest).join(", ");
                format!("{first} and {last}")
            }
        };
        reasons.push(format!("{} printings match {by}", remaining.len()));
    }
    Ok(Matched::Loose(
        card,
        format!(
            "{}; used {} {} ({}).",
            reasons.join("; "),
            illust.card_number,
            illust.rarity,
            variant(illust, CardLanguage::Japanese).unwrap_or_default()
        ),
    ))
}

fn match_row(
    row: &Row,
    amount: u32,
    index: &DbIndex,
    db: &CardsDatabase,
    catalog: &ProductsDatabase,
) -> Result<Matched, String> {
    let mut notes: Vec<String> = vec![];

    // tries one way of identifying the printing; `None` moves on to the next one
    let mut by = |label: String, found: Vec<usize>| {
        let found = found
            .into_iter()
            .sorted()
            .dedup()
            .map(|p| index.card(p, amount))
            .filter(|c| row.number_matches(c))
            .collect_vec();
        let earlier = |notes: &[String]| {
            if notes.is_empty() {
                String::new()
            } else {
                format!("{}; ", notes.join("; "))
            }
        };
        match found.as_slice() {
            [] => {
                notes.push(format!("{label} not found"));
                None
            }
            [card] if notes.is_empty() => Some(Matched::Exact(card.clone())),
            [card] => Some(Matched::Loose(
                card.clone(),
                format!("{}matched by {label} instead.", earlier(&notes)),
            )),
            [card, ..] => Some(Matched::Loose(
                card.clone(),
                format!(
                    "{}{label} matches {} printings; used {} ({}).",
                    earlier(&notes),
                    found.len(),
                    card.card_number,
                    card.card_illustration(db)
                        .and_then(|i| variant(i, CardLanguage::Japanese))
                        .unwrap_or_default(),
                ),
            )),
        }
    };

    // 1. card id, with its language (both when missing), or official URL
    if !row.card_ids.is_empty() || !row.official_urls.is_empty() {
        let languages = row.language.map_or(LANGUAGES.to_vec(), |l| vec![l]);
        let ids = join(&row.card_ids);
        let label = match (row.card_ids.is_empty(), row.language) {
            (true, _) => "Official URL".to_string(),
            (false, Some(l)) => format!("Card ID {ids} ({})", lang_code(l)),
            (false, None) => format!("Card ID {ids}"),
        };
        // the official page has the card id and language; it is only used without a Card ID
        let found = if row.card_ids.is_empty() {
            row.official_urls
                .iter()
                .flat_map(|url| index.by_official_url(url))
                .collect()
        } else {
            index.by_card_ids(&row.card_ids, &languages)
        };
        if let Some(found) = by(label, found) {
            return Ok(found);
        }
    }

    // 2. image path or URL
    if !row.variants.is_empty() {
        let label = format!("variant \"{}\"", join(&row.variants));
        let found = row.variants.iter().flat_map(|v| index.by_variant(v));
        if let Some(found) = by(label, found.collect()) {
            return Ok(found);
        }
    }

    // 3. TCGplayer product ids or URLs
    if !row.tcgplayer.is_empty() {
        let label = format!("TCGplayer {}", join(&row.tcgplayer));
        let found = row.tcgplayer.iter().flat_map(|v| index.by_tcgplayer(v));
        if let Some(found) = by(label, found.collect()) {
            return Ok(found);
        }
    }

    // 4. Yuyu-tei URLs or sell paths
    if !row.yuyutei.is_empty() {
        let label = format!("Yuyu-tei URL {}", join(&row.yuyutei));
        let found = row.yuyutei.iter().flat_map(|v| index.by_yuyutei(v));
        if let Some(found) = by(label, found.collect()) {
            return Ok(found);
        }
    }

    // 5. card number, narrowed by rarity, set and illustrator
    let matched = match_by_attributes(row, amount, db, catalog)?;
    Ok(match (matched, notes.is_empty()) {
        (matched, true) => matched,
        (Matched::Exact(card), false) => Matched::Loose(
            card,
            format!("{}; matched by card number instead.", notes.join("; ")),
        ),
        (Matched::Loose(card, message), false) => {
            Matched::Loose(card, format!("{}; {message}", notes.join("; ")))
        }
    })
}

/// Column positions in a file without a header: card number, and quantity when there is one.
fn guess_columns(record: &[String], db: &CardsDatabase) -> Option<Vec<(Column, usize)>> {
    let number = record
        .iter()
        .position(|f| known_card_number(f, db).is_some())?;
    let mut columns = vec![(Column::CardNumber, number)];
    if let Some(quantity) = record
        .iter()
        .enumerate()
        .position(|(i, f)| i != number && parse_quantity(f).is_some())
    {
        columns.push((Column::Quantity, quantity));
    }
    Some(columns)
}

/// Imports CSV text. A `Deck` column rebuilds a deck, otherwise a pile of cards.
pub fn import_csv(
    text: &str,
    db: &CardsDatabase,
    catalog: &ProductsDatabase,
) -> Result<CsvImport, String> {
    let text = text.trim_start_matches(BOM);
    let records = parse_records(text, detect_delimiter(text));
    let Some((_, first)) = records.first() else {
        return Err("The file is empty.".into());
    };

    // header, or a headerless list of card numbers
    let mut header: Vec<(Column, usize)> = vec![];
    for (i, name) in first.iter().enumerate() {
        if let Some(column) = Column::from_header(name)
            && !header.iter().any(|(c, _)| *c == column)
        {
            header.push((column, i));
        }
    }
    let (columns, data) = if header.iter().any(|(c, _)| c.identifies_card()) {
        (header, &records[1..])
    } else if let Some(columns) = guess_columns(first, db) {
        (columns, &records[..])
    } else {
        return Err(
            "No card column found. Add a header row with \"Card Number\" (or \"Card ID\") and \"Quantity\"."
                .into(),
        );
    };
    let has_section = columns.iter().any(|(c, _)| *c == Column::Deck);
    let index = DbIndex::new(db);

    let mut issues = vec![];
    let mut cards = vec![];
    for (row_number, record) in data {
        let get = |column: Column| {
            columns
                .iter()
                .find(|(c, _)| *c == column)
                .and_then(|(_, i)| record.get(*i))
                .map(|v| v.trim())
                .filter(|v| !v.is_empty())
        };
        let mut skip = |message: String| {
            issues.push(ImportIssue {
                row: *row_number,
                kind: IssueKind::Skipped,
                message,
            })
        };

        let amount = match get(Column::Quantity) {
            None => 1,
            Some(value) => match parse_quantity(value) {
                Some(0) => continue,
                Some(amount) => amount,
                None => {
                    skip(format!("Invalid quantity \"{value}\"."));
                    continue;
                }
            },
        };

        let mut set = get(Column::SetName).map(String::from);
        let mut set_code = get(Column::SetCode).map(String::from);
        let mut card_number = get(Column::CardNumber).and_then(|v| known_card_number(v, db));
        if card_number.is_none() {
            // "set code" columns sometimes hold card numbers
            for value in [&mut set_code, &mut set] {
                if card_number.is_none()
                    && let Some(number) = value.as_deref().and_then(|v| known_card_number(v, db))
                {
                    card_number = Some(number);
                    *value = None;
                }
            }
        }
        // an unknown card number is still reported as such
        let card_number = card_number.or(get(Column::CardNumber).map(String::from));
        let all = |column: Column| get(column).map(cell_values).unwrap_or_default();
        let row = Row {
            card_number,
            rarity: get(Column::Rarity).map(String::from),
            set,
            set_code,
            illustrator: get(Column::Illustrator).map(String::from),
            language: get(Column::Language).and_then(parse_language),
            card_ids: get(Column::CardId).map(cell_numbers).unwrap_or_default(),
            official_urls: all(Column::OfficialUrl),
            variants: [all(Column::Variant), all(Column::ImageUrl)]
                .concat()
                .iter()
                .map(|v| normalize_variant(v))
                .collect(),
            tcgplayer: all(Column::TcgplayerUrl),
            yuyutei: all(Column::YuyuteiUrl),
        };
        let section = get(Column::Deck).and_then(parse_section);

        match match_row(&row, amount, &index, db, catalog) {
            Ok(Matched::Exact(card)) => cards.push((*row_number, card, section)),
            Ok(Matched::Loose(card, message)) => {
                issues.push(ImportIssue {
                    row: *row_number,
                    kind: IssueKind::Loose,
                    message,
                });
                cards.push((*row_number, card, section));
            }
            Err(message) => skip(message),
        }
    }

    let deck = if has_section {
        let mut deck = CommonDeck::default();
        for (row, card, section) in cards {
            match card.card_type(db).or(section).unwrap_or(CardType::Main) {
                CardType::Oshi => match &mut deck.oshi {
                    None => deck.oshi = Some(card),
                    Some(oshi)
                        if oshi.card_number == card.card_number
                            && oshi.illustration_idx == card.illustration_idx =>
                    {
                        oshi.amount += card.amount
                    }
                    Some(_) => issues.push(ImportIssue {
                        row,
                        kind: IssueKind::Skipped,
                        message: format!("A deck has only one oshi; {} ignored.", card.card_number),
                    }),
                },
                CardType::Main => deck.main_deck.push(card),
                CardType::Cheer => deck.cheer_deck.push(card),
            }
        }
        deck.merge();
        DeckOrPile::Deck(deck)
    } else {
        DeckOrPile::Pile(PileOfCards {
            name: None,
            cards: cards
                .into_iter()
                .map(|(_, card, _)| card)
                .collect_vec()
                .merge(),
        })
    };
    issues.sort_by_key(|i| i.row);

    Ok(CsvImport {
        deck,
        rows: data.len(),
        issues,
    })
}

