    #[test]
    fn any_column_subset_round_trips() {
        let db = fixture_db();
        let catalog = fixture_products();
        let pile = DeckOrPile::Pile(all_printings(&db));
        let deck = sample_deck(&db);
        let subsets = [
            vec![],
            Column::defaults(true, CardLanguage::Japanese),
            Column::defaults(true, CardLanguage::English),
            Column::ALL.to_vec(),
            vec![Column::Name, Column::Rarity, Column::SetName],
            vec![Column::CardNumber, Column::SetCode, Column::PriceUsd],
        ];
        for columns in &subsets {
            for language in LANGUAGES {
                for expected in [&pile, &deck] {
                    let csv = export_with(expected, language, &db, &catalog, columns);
                    let imported = import(&csv, &db).unwrap();
                    assert_eq!(imported.issues, vec![], "{columns:?} {language:?}");
                    assert_eq!(&imported.deck, expected, "{columns:?} {language:?}");
                }
            }
        }

        // the minimum the import needs
        let csv = export_with(&pile, CardLanguage::Japanese, &db, &catalog, &[]);
        assert_eq!(
            csv.lines().next(),
            Some("Quantity,Language,Card ID,Variant")
        );
        let csv = export_with(&deck, CardLanguage::Japanese, &db, &catalog, &[]);
        assert_eq!(
            csv.lines().next(),
            Some("Deck,Quantity,Language,Card ID,Variant")
        );
    }

    #[test]
    fn header_order_does_not_depend_on_the_selection() {
        let db = fixture_db();
        let catalog = fixture_products();
        let deck = sample_deck(&db);
        let columns = vec![Column::Notes, Column::Rarity, Column::Name, Column::Deck];
        let reversed = columns.iter().rev().copied().collect_vec();
        let csv = export_with(&deck, CardLanguage::English, &db, &catalog, &columns);
        assert_eq!(
            csv,
            export_with(&deck, CardLanguage::English, &db, &catalog, &reversed)
        );
        assert_eq!(
            csv.lines().next(),
            Some("Deck,Quantity,Name,Rarity,Language,Card ID,Variant,Notes")
        );
        // the selection helper keeps the same order, with the required columns
        let mut choices = BTreeMap::new();
        choices.insert(Column::Notes, false);
        choices.insert(Column::FullSetName, true);
        choices.insert(Column::CardId, false);
        let selection = Column::selection(&choices, false, CardLanguage::Japanese);
        assert!(selection.contains(&Column::CardId));
        assert!(selection.contains(&Column::FullSetName));
        assert!(!selection.contains(&Column::Notes));
        assert!(!selection.contains(&Column::Deck));
        assert!(selection.windows(2).all(|w| {
            let position = |c| Column::ALL.iter().position(|x| *x == c);
            position(w[0]) < position(w[1])
        }));
    }

    #[test]
    fn niche_columns() {
        let db = fixture_db();
        let catalog = fixture_products();
        let cards = vec![
            card(&db, "hBP01-007", |i| i.rarity.to_string() == "OSR"),
            by_id(&db, 2811),
            by_id(&db, 2992),
            by_id(&db, 53),
            by_id(&db, 120),
            by_id(&db, 1174),
            by_id(&db, 834),
            card(&db, "hBP01-108", |i| {
                has_manage_id(i, CardLanguage::English, 1123)
            }),
        ];
        let jp = export_with(
            &pile(cards.clone()),
            CardLanguage::Japanese,
            &db,
            &catalog,
            &Column::ALL,
        );
        let en = export_with(
            &pile(cards.clone()),
            CardLanguage::English,
            &db,
            &catalog,
            &Column::ALL,
        );

        // card types and colors in the name language
        let oshi = row(&jp, "35");
        assert_eq!(oshi["Card Type"], "推しホロメン");
        let en_oshi = row(&en, &oshi["Card Number"]);
        assert_eq!(en_oshi["Card Type"], "Oshi Holo Member");
        assert_eq!(en_oshi["Color"], "Blue");
        assert_eq!(oshi["Life"], "5");
        assert_eq!(oshi["HP"], "");
        let holomem = row(&jp, "120");
        assert_eq!(holomem["Card Type"], "2nd ホロメン");
        assert_eq!(holomem["HP"], "210");
        assert_eq!(holomem["Product Category"], "boosters");

        // released only in Japanese: the short Japanese name
        let u = row(&jp, "2811");
        assert_eq!(u["Card Type"], "サポート・イベント・LIMITED");
        assert_eq!(u["Set Name"], "ボリュームヴォルテックス");

        let p = row(&jp, "2992");
        assert_eq!(p["Source"], "Basic PR Pack vol 13");
        assert_eq!(p["Product Category"], "pr");
        // no short name: the official name
        assert_eq!(p["Set Name"], "PRカード");

        // an art exclusive to a set has a source, but is not a promo
        let sr = row(&jp, "1174");
        assert_eq!(sr["Source"], "1st Anniversary Celebration Set");
        assert_eq!(sr["Set Name"], "1st Anniversary Celebration Set");
        assert_eq!(sr["Product Category"], "accessories");

        // sources are per language
        assert_eq!(
            row(&jp, "834")["Source"],
            "World Grand Prix May 2025 participation"
        );
        // a printing released only in Japanese is the Japanese one, with its source
        let jp_promo = row(&en, "hPR/hBP01-108_P");
        assert_eq!(jp_promo["Language"], "JP");
        assert_eq!(jp_promo["Source"], row(&jp, "hPR/hBP01-108_P")["Source"]);
        assert_eq!(
            row(&en, "1123")["Source"],
            "Bloom Cup January-March 2026 participation"
        );

        let c = row(&en, "3");
        assert_eq!(
            c["Set Name"],
            "Start Deck Tokino Sora & AZKi\nBlooming Radiance"
        );
        assert_eq!(c["Product Category"], "decks\nboosters");
        // no price check: the empty price columns are left out
        assert!(!c.contains_key("Price (JPY)"));
        assert!(!c.contains_key("Price (USD)"));
    }

    #[test]
    fn price_columns() {
        use crate::sources::price_check::PriceCacheKey;
        use jiff::Timestamp;

        let db = fixture_db();
        let card = by_id(&db, 53);
        let illust = card.card_illustration(&db).unwrap();
        // test data, not real prices
        let mut prices = PriceCache::new();
        for path in illust.yuyutei_sell_paths.iter().flatten() {
            prices.insert(
                PriceCacheKey::Yuyutei(path.clone()),
                (Timestamp::now(), Price::Yen(30)),
            );
        }
        for id in illust.tcgplayer_product_ids.iter().flatten() {
            prices.insert(
                PriceCacheKey::TcgPlayer(*id),
                (Timestamp::now(), Price::Dollar(105)),
            );
        }
        let data = ExportData {
            db: &db,
            catalog: &fixture_products(),
            prices: &prices,
        };
        let csv = export_csv(
            &pile(vec![card]),
            &data,
            &[Column::PriceJpy, Column::PriceUsd],
            &ExportOptions::new(CardLanguage::English),
        );
        let row = row(&csv, "3");
        assert_eq!(row["Price (JPY)"], "30");
        assert_eq!(row["Price (USD)"], "1.05");
    }

