    #[test]
    fn quoting() {
        let mut out = String::new();
        write_record(
            &mut out,
            [
                "So, That Makes You My Enemy",
                "say \"hi\"",
                "a\nb",
                " x",
                "plain",
                "",
            ],
        );
        assert_eq!(
            out,
            "\"So, That Makes You My Enemy\",\"say \"\"hi\"\"\",\"a\nb\",\" x\",plain,\r\n"
        );
        assert_eq!(
            parse_records(&out, ','),
            vec![(
                1,
                vec![
                    "So, That Makes You My Enemy".to_string(),
                    "say \"hi\"".into(),
                    "a\nb".into(),
                    " x".into(),
                    "plain".into(),
                    "".into(),
                ]
            )]
        );

        let db = fixture_db();
        let enemy = find(&db, |i| {
            db.get(&i.card_number)
                .is_some_and(|c| c.name.english.as_deref() == Some("So, That Makes You My Enemy"))
        })
        .unwrap();
        let csv = export(&pile(vec![enemy]), CardLanguage::English, &db);
        assert!(csv.contains(",\"So, That Makes You My Enemy\","), "{csv}");
    }

