    #[test]
    fn sets_come_from_the_catalog() {
        let db = fixture_db();
        let cards = vec![
            by_id(&db, 2811),
            by_id(&db, 2991),
            by_id(&db, 53),
            by_id(&db, 2510),
        ];
        let jp = export_all(&pile(cards.clone()), CardLanguage::Japanese, &db);
        let en = export_all(&pile(cards.clone()), CardLanguage::English, &db);

        let u = row(&jp, "2811");
        assert_eq!(
            u["Full Set Name"],
            "ブースターパック「ボリュームヴォルテックス」"
        );
        assert_eq!(u["Set Code"], "hBP09");
        assert_eq!(u["Release Date"], "2026-09-19");
        let p = row(&jp, "2991");
        assert_eq!(p["Full Set Name"], "PRカード");
        assert_eq!(p["Set Code"], "hPR");
        assert_eq!(p["Release Date"], "");
        // the PR pack is the source
        assert_eq!(p["Source"], "Basic PR Pack vol 13");

        // names, codes and dates of each language
        let c = row(&jp, "53");
        assert_eq!(
            c["Full Set Name"],
            "ブースターパック「ブルーミングレディアンス」"
        );
        assert_eq!(c["Set Code"], "hBP01");
        assert_eq!(c["Release Date"], "2024-09-20");
        let c = row(&en, "3");
        assert_eq!(
            c["Full Set Name"],
            "Start Deck – Tokino Sora & AZKi\nBooster Pack – Blooming Radiance"
        );
        assert_eq!(c["Set Code"], "hSD01\nhBP01");
        assert_eq!(c["Release Date"], "2025-07-11");
        let c = row(&jp, "2510");
        assert_eq!(
            c["Full Set Name"],
            "エクストラブースター サマー・ホログラム"
        );
        assert_eq!(c["Release Date"], "2026-08-21");
        let c = row(&en, "1777");
        assert_eq!(c["Full Set Name"], "Extra Booster – Summer hologram");
        assert_eq!(c["Set Code"], "hEB01");
        assert_eq!(c["Release Date"], "2026-09-25");

        // not released in English: the Japanese printing, its products named in English when
        // the catalog can
        let u = row(&en, "hBP09/hBP09-094_U");
        assert_eq!(
            u["Full Set Name"],
            "ブースターパック「ボリュームヴォルテックス」"
        );
        assert_eq!(u["Set Code"], "hBP09");
        assert_eq!(u["Release Date"], "2026-09-19");
        let p = row(&en, "hPR/hBP09-094_P");
        assert_eq!(p["Full Set Name"], "PROMO CARDS");
        assert_eq!(p["Release Date"], "");

        // catalog names (both languages) and codes select the printing
        for (rarity, set, set_code, id) in [
            ("C", "Booster Pack – Blooming Radiance", "", 53),
            ("C", "ブースターパック「ブルーミングレディアンス」", "", 53),
            ("C", "Start Deck – Tokino Sora & AZKi", "", 53),
            ("C", "", "hSD01", 53),
            ("C", "Extra Booster – Summer hologram", "", 2510),
            ("C", "エクストラブースター サマー・ホログラム", "", 2510),
            ("C", "", "hEB01", 2510),
            ("C", "Booster Pack hEB01", "", 2510),
            ("P", "PROMO CARDS", "", 189),
        ] {
            let csv =
                format!("Card Number,Rarity,Set,Set Code\nhBP01-021,{rarity},{set},{set_code}\n");
            let (cards, issues) = import_pile(&csv, &db);
            assert_eq!(issues, vec![], "{csv}");
            assert_eq!(cards, vec![by_id(&db, id)], "{csv}");
        }
    }

    #[test]
    fn without_the_catalog() {
        let db = fixture_db();
        let none = ProductsDatabase::new();
        let cards = vec![by_id(&db, 53), by_id(&db, 2811)];
        let jp = export_with(
            &pile(cards.clone()),
            CardLanguage::Japanese,
            &db,
            &none,
            &Column::ALL,
        );
        let en = export_with(
            &pile(cards.clone()),
            CardLanguage::English,
            &db,
            &none,
            &Column::ALL,
        );
        for (csv, number, code) in [
            (&jp, "hBP01-021", "hBP01"),
            (&en, "hBP01-021", "hSD01\nhBP01"),
            (&jp, "hBP09-094", "hBP09"),
            (&en, "hBP09-094", "hBP09"),
        ] {
            let row = row(csv, number);
            // the empty columns are left out
            assert!(!row.contains_key("Full Set Name"), "{number}");
            assert_eq!(row["Set Code"], code, "{number}");
            assert!(!row.contains_key("Release Date"), "{number}");
        }

        // codes still select the printing, names can't
        let csv = "Card Number,Rarity,Set Code\nhBP01-021,C,hEB01\n";
        let imported = import_csv(csv, &db, &none).unwrap();
        assert_eq!(imported.issues, vec![]);
        assert_eq!(imported.deck, pile(vec![by_id(&db, 2510)]));
        let csv = "Card Number,Rarity,Set\nhBP01-021,C,Extra Booster – Summer hologram\n";
        let imported = import_csv(csv, &db, &none).unwrap();
        assert_eq!(imported.issues.len(), 1);
        assert_eq!(imported.issues[0].kind, IssueKind::Loose);
    }

